{
  "parents": [
    {
      "name": "Swift-Hohenberg equation",
      "canonical_form": "u_t = r u - (u_xx + 1)^2 u?  Actually canonical is: u_t = r u - (1 + \\partial_x^2)^2 u + N(u)",
      "term_mapping": "Parent has linear term r u, fourth-order term -u_xxxx, second-order term -2 u_xx, and a nonlinear term N(u). The discovered equation: pump*u (with pump = 1.5*exp(-0.1*x^2)) replaces constant r u; -2.0*u_xx matches the second-order cross term; -1.0*u_xxxx matches fourth-order; u^3 - u^5 is a modified nonlinearity (cubic + quintic). All terms present, but the linear coefficient is spatially varying (gaussian) and nonlinearity is saturating.",
      "symbol_roles": "u is a scalar field (e.g. convection rolls amplitude), x is lateral coordinate, t is time, r is linear growth/decay rate, coefficients control pattern selection and saturation.",
      "fit": "high"
    },
    {
      "name": "Kolmogorov-Petrovskii-Piskunov (Fisher) / reaction-diffusion equation",
      "canonical_form": "u_t = D u_xx + f(u)",
      "term_mapping": "Parent has diffusion D u_xx and reaction f(u). Discovered has -2.0*u_xx (diffusion, negative, so anti-diffusion), -1.0*u_xxxx (added stabilising fourth-order term), pump*u (added space-dependent linear source), -u^3+u^5 (nonlinear reaction with cubic and quintic terms). So relative to Fisher: same u_t and u_xx, but reaction term is modified with spatial pumping and higher-order nonlinear terms; fourth-order term added.",
      "symbol_roles": "u is concentration or population density, x space, t time, D diffusion coefficient, f(u) reaction rate (growth/decay).",
      "fit": "medium"
    },
    {
      "name": "Nonlinear Schrödinger (NLS) equation (real form / pattern forming)",
      "canonical_form": "i u_t = u_xx + |u|^2 u (or with constants) ; but real counterpart: u_t = -u_xx - u^3",
      "term_mapping": "Parent real NLS has u_t = -u_xx - u^3 (with sign choices). Discovered has -2*u_xx instead of -1* u_xx (amplitude modified), added -u_xxxx (dispersion/regularisation), added pump*u (space-dependent potential), added +u^5 (quintic saturation). So u_xx and u^3 are present but coefficients modified; additional terms are pump, u^5, and u_xxxx.",
      "symbol_roles": "u is complex wavefunction amplitude (here real), x is spatial coordinate, t is time, u_xx is kinetic/dispersive term, cubic term is Kerr nonlinearity, quintic term is higher-order nonlinearity.",
      "fit": "medium"
    },
    {
      "name": "Kuramoto-Sivashinsky equation (generalised)",
      "canonical_form": "u_t = -u_xx - u_xxxx + u u_x + ... (classic: u_t = -u_xx - u_xxxx + u u_x)",
      "term_mapping": "Classic KS has second-order (negative diffusion) and fourth-order (dissipation) terms. Discovered has -2.0*u_xx and -1.0*u_xxxx (same structure but no advective nonlinearity u u_x), instead added pump*u (space-dependent linear term) and polynomial nonlinearity -u^3+u^5. So second and fourth order terms match, but advection term dropped, linear term modified, nonlinearity replaced.",
      "symbol_roles": "u is a field (e.g. flame front height, phase turbulence), x space, t time, u_xx drives instability, u_xxxx stabilises, u u_x is nonlinear convection.",
      "fit": "medium"
    },
    {
      "name": "Cahn-Hilliard (or Swift-Hohenberg-like) equation with external forcing",
      "canonical_form": "u_t = -\\partial_x^2 (u - u^3 + u_xx) + ... (actually: u_t = \\partial_x^2( -u + u^3 - u_xx ) )",
      "term_mapping": "Parent Cahn-Hilliard has u_t = -u_xxxx + u_xx + ...? Actually classic: u_t = \\partial_x^2( -u + u^3 - u_xx ) = -u_xxxx + u_xx + \\partial_x^2(u^3). Discovered has -u_xxxx and -2u_xx (signs opposite to CH for u_xx) and -u^3+u^5 (not inside x-derivative), plus pump*u. So the fourth-order term matches (with opposite sign for u_xx) but nonlinearity is local not conservative; pumped term is external field.",
      "symbol_roles": "u is order parameter (e.g. concentration), x is spatial coordinate, t is time, u_xxxx is interfacial energy, u_xx is capillarity, u^3 is double-well potential nonlinearity, u^5 is higher-order saturation.",
      "fit": "low"
    },
    {
      "name": "Generalised Ginzburg-Landau amplitude equation",
      "canonical_form": "u_t = a u + b u_xx + c |u|^2 u + d |u|^4 u + ... (complex or real)",
      "term_mapping": "Canonical real GL has linear term a u, diffusion b u_xx, cubic term c u^3, quintic term d u^5. Discovered has pump*u (a is space-dependent), -2.0*u_xx, -1.0*u_xxxx added (extra stabilisation), -u^3+u^5. So cubic and quintic terms present, linear term modified to gaussian pump, diffusion present, fourth-order added.",
      "symbol_roles": "u is slowly varying amplitude of a pattern, x is spatial coordinate, t is time, a is linear growth/damping, b diffusion/dispersion, c cubic nonlinearity coefficient, d quintic saturation coefficient.",
      "fit": "high"
    }
  ]
}
